export function downloadCsvForBatch(batch, tokens = []) {
  const headers = [
    'Token Code',
    'Batch Number',
    'Product Name',
    'Product Type',
    'Artisan Name',
    'Artisan ID',
    'Artisan Facility',
    'Source Cow IDs',
    'Manufacturing Date',
    'Expiry Date',
    'Net Weight/Unit',
    'Status',
    'Verification URL',
    'Generated At',
    'Generated By'
  ];

  const escapeCsv = (val) => {
    if (val === null || val === undefined) return '""';
    const str = String(val).replace(/"/g, '""');
    return `"${str}"`;
  };

  const rows = tokens.length > 0 ? tokens.map(t => [
    escapeCsv(t.tokenCode),
    escapeCsv(batch.batchNumber),
    escapeCsv(batch.productName),
    escapeCsv(batch.productType),
    escapeCsv(batch.artisanName),
    escapeCsv(batch.artisanId),
    escapeCsv(batch.artisanFacility),
    escapeCsv(Array.isArray(batch.sourceCowIds) ? batch.sourceCowIds.join('; ') : batch.sourceCowIds),
    escapeCsv(batch.manufacturingDate),
    escapeCsv(batch.expiryDate),
    escapeCsv(batch.unit),
    escapeCsv(t.status),
    escapeCsv(t.verificationUrl),
    escapeCsv(t.generatedAt),
    escapeCsv(t.generatedBy)
  ]) : [
    [
      escapeCsv('NO_TOKENS_YET'),
      escapeCsv(batch.batchNumber),
      escapeCsv(batch.productName),
      escapeCsv(batch.productType),
      escapeCsv(batch.artisanName),
      escapeCsv(batch.artisanId),
      escapeCsv(batch.artisanFacility),
      escapeCsv(Array.isArray(batch.sourceCowIds) ? batch.sourceCowIds.join('; ') : batch.sourceCowIds),
      escapeCsv(batch.manufacturingDate),
      escapeCsv(batch.expiryDate),
      escapeCsv(batch.unit),
      escapeCsv(batch.status),
      escapeCsv('N/A'),
      escapeCsv(batch.createdAt),
      escapeCsv(batch.createdBy)
    ]
  ];

  const csvContent = '\uFEFF' + [headers.join(','), ...rows.map(r => r.join(','))].join('\r\n');
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.setAttribute('href', url);
  link.setAttribute('download', `${batch.batchNumber}-Verification-Tokens.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}
